<?php
/**
 * LoginSettings - from docs/handover/artifact-source/LoginSettings.dc.html (scripts/sl_convert.py), bound to login_settings.php.
 * Shell page: yes. Gate: view_tools. Writes: ajax/sl/login_settings_ajax.php.
 * Data contract ($d): slides[{cls,url,title,sub,on}], look{blur,dim,interval,captions,pages[],texts}, pv, cur, curN, onCount, logo, favicon, site
 * Logo and favicon are managed on the existing Settings › Logo page (shown here read-only).
 */
if (!isset($d)) { $d = []; }
$ep = 'ajax/sl/login_settings_ajax.php';
$look = sl_get($d, 'look', []);
$slides = (array) sl_get($d, 'slides', []);
$pv = sl_get($d, 'pv', 'login');
$cur = sl_get($d, 'cur');
$PG = [['login', 'Log in', 'i-lock', 'Main sign-in page'], ['register', 'Register', 'i-user', 'Create an account'], ['forgot', 'Forgot password', 'i-key', 'Reset with a code'], ['otp', 'Code check (OTP)', 'i-message', 'Email or WhatsApp code']];
$PF = ['login' => ['Username or email', 'Password'], 'register' => ['First and last name', 'Email', 'Phone (WhatsApp)', 'Password'], 'forgot' => ['Email address'], 'otp' => ['6-digit code']];
$defaults = ['login' => ['Welcome back', 'Log in'], 'register' => ['Create your account', 'Create my account'], 'forgot' => ['Forgot your password?', 'Send me a code'], 'otp' => ['Enter your login code', 'Verify and log in']];
$tx = (array) ($look['texts'] ?? []);
$txt = fn($pg, $i) => (string) (($tx[$pg][$i] ?? null) ?: $defaults[$pg][$i]);
$pages = (array) ($look['pages'] ?? []);
$bgSty = fn($s) => $s && $s['url'] !== '' ? 'background-image:url(' . $s['url'] . ')' : '';
?>
<div class="row g8 mut sm"><a href="<?= sl_route('SettingsHub') ?>">Settings</a><i class="ic ic-sm i-right" aria-hidden="true"></i><span style="color:var(--ink)">Login page</span></div>
<div class="sl-head"><div><h1 class="sl-title" style="font-size:20px">Login, register and branding</h1><p class="sl-lede">Pictures behind the sign-in, register and password pages, plus the page texts. Check every page in the preview.</p></div><div class="row g8 wrap"><a class="sl-btn ghost" href="<?= sl_route('Login') ?>" target="_blank" rel="noopener"><i class="ic ic-sm i-eye" aria-hidden="true"></i>Open login page</a><button class="sl-btn" type="submit" form="ls-form"><i class="ic ic-sm i-check" aria-hidden="true"></i>Save changes</button></div></div>
<div class="split">
<div class="a col g16">
<section class="sl-card col g12"><div class="sl-ch" style="margin:0"><h2 class="sl-ct">Pictures</h2><span class="mut sm"><?= (int) sl_get($d, 'onCount') ?> of <?= count($slides) ?> showing</span></div>
<form class="ls-drop" id="ls-upload" action="<?= $ep ?>" enctype="multipart/form-data" style="position:relative"><input type="hidden" name="op" value="upload"><input type="file" name="pictures[]" accept="image/jpeg,image/png,image/webp" multiple aria-label="Upload pictures"><span class="sl-tile"><i class="ic i-upload" aria-hidden="true"></i></span><b class="fw5">Drop pictures here or click to upload</b><span class="mut sm">JPG, PNG or WEBP, at least 1920 × 1080. Up to 8 pictures.</span></form>
<?php foreach ($slides as $i => $s): ?><div class="ls-sl <?= $s['on'] ? '' : 'off' ?>"><span class="mono mut" style="text-align:center"><?= $i + 1 ?></span><div class="ls-th <?= h($s['cls']) ?>" style="<?= h($bgSty($s)) ?>"></div><div class="col g6"><input class="sl-in" style="height:36px" aria-label="Caption title <?= $i + 1 ?>" name="title[<?= $i ?>]" form="ls-form" maxlength="80" value="<?= h($s['title']) ?>" placeholder="Caption title"><input class="sl-in" style="height:34px;font-size:15px" aria-label="Caption line <?= $i + 1 ?>" name="sub[<?= $i ?>]" form="ls-form" maxlength="120" value="<?= h($s['sub']) ?>" placeholder="Caption line"></div><div class="col g6" style="align-items:flex-end"><span class="sl-toggle <?= $s['on'] ? 'on' : '' ?>" role="switch" aria-checked="<?= $s['on'] ? 'true' : 'false' ?>" aria-label="Show picture <?= $i + 1 ?>" data-sl-save="<?= $ep ?>" data-p-op="toggle" data-p-i="<?= $i ?>"></span><div class="row g4"><?php if ($i > 0): ?><button class="sl-ib" type="button" aria-label="Move up" data-sl-action="<?= $ep ?>" data-p-op="up" data-p-i="<?= $i ?>"><i class="ic ic-sm i-up" aria-hidden="true"></i></button><?php endif; ?><a class="sl-ib" aria-label="Preview picture <?= $i + 1 ?>" href="<?= h(sl_url(['n' => count(array_filter(array_slice($slides, 0, $i), fn($x) => $x['on']))])) ?>"><i class="ic ic-sm i-eye" aria-hidden="true"></i></a><?php if (count($slides) > 1): ?><button class="sl-ib" type="button" aria-label="Delete picture <?= $i + 1 ?>" data-sl-action="<?= $ep ?>" data-p-op="delete" data-p-i="<?= $i ?>" data-sl-confirm="Delete picture <?= $i + 1 ?>?"><i class="ic ic-sm i-trash" aria-hidden="true"></i></button><?php endif; ?></div></div></div><?php endforeach; ?>
<button class="sl-btn ghost sm" type="button" style="align-self:flex-start" data-sl-action="<?= $ep ?>" data-p-op="reset" data-sl-confirm="Replace all pictures with the three default ones?"><i class="ic ic-sm i-refresh" aria-hidden="true"></i>Use the default pictures</button></section>
<section class="sl-card col g12"><div class="sl-ch" style="margin:0"><h2 class="sl-ct">Pages that show the pictures</h2><span class="mut sm"><?= count(array_intersect($pages, ['login', 'register', 'forgot', 'otp'])) ?> of 4 pages</span></div><div class="grid cols2" style="gap:8px"><?php foreach ($PG as $p): $on = in_array($p[0], $pages, true); ?><div class="ls-pg <?= $on ? '' : 'off' ?>"><span class="sl-tile"><i class="ic ic-sm <?= h($p[2]) ?>" aria-hidden="true"></i></span><span class="col grow"><b class="fw5 sm"><?= h($p[1]) ?></b><span class="mut" style="font-size:14px"><?= h($p[3]) ?><?= $p[0] === 'register' ? ' (register page has no picture area)' : '' ?></span></span><span class="sl-toggle <?= $on ? 'on' : '' ?>" role="switch" aria-checked="<?= $on ? 'true' : 'false' ?>" aria-label="<?= h($p[1]) ?>" data-sl-save="<?= $ep ?>" data-p-op="page" data-p-page="<?= h($p[0]) ?>"></span><a class="sl-ib" style="width:36px;height:36px" aria-label="Preview <?= h($p[1]) ?>" href="<?= h(sl_url(['pv' => $p[0]])) ?>"><i class="ic ic-sm i-eye" aria-hidden="true"></i></a></div><?php endforeach; ?></div></section>
<section class="sl-card col g12"><h2 class="sl-ct">Logo and favicon</h2><div class="grid cols2" style="gap:12px">
<a class="ls-up" href="<?= sl_route('SettingsHub', ['tab' => 'logo']) ?>" style="color:inherit"><span class="ls-logo" style="<?= sl_get($d, 'logo') ? 'background-image:url(' . h(sl_get($d, 'logo')) . ')' : '' ?>"><?php if (!sl_get($d, 'logo')): ?><span class="sl-logo"><i></i></span><?php endif; ?></span><span class="col"><b class="fw5 sm">Logo</b><span class="mut" style="font-size:14px"><?= sl_get($d, 'logo') ? 'Shown on login, labels and e-mails' : 'Not set' ?></span><span class="sm fw5" style="color:var(--ink)">Change in Settings</span></span></a>
<a class="ls-up" href="<?= sl_route('SettingsHub', ['tab' => 'logo']) ?>" style="color:inherit"><span class="ls-fav" style="<?= sl_get($d, 'favicon') ? 'background-image:url(' . h(sl_get($d, 'favicon')) . ');background-color:transparent' : '' ?>"><?php if (!sl_get($d, 'favicon')): ?><b>SL</b><?php endif; ?></span><span class="col"><b class="fw5 sm">Favicon</b><span class="mut" style="font-size:14px"><?= sl_get($d, 'favicon') ? 'Shown in the browser tab' : 'Not set' ?></span><span class="sm fw5" style="color:var(--ink)">Change in Settings</span></span></a></div></section>
<form class="col g16" id="ls-form" data-sl-form action="<?= $ep ?>"><input type="hidden" name="op" value="save">
<section class="sl-card col g12"><h2 class="sl-ct">Texts on each page</h2><?php foreach (['login' => 'Log in', 'register' => 'Register', 'forgot' => 'Forgot password'] as $pg => $lbl): ?><div class="grid cols2" style="gap:10px"><label class="sl-field"><span class="sl-lab"><?= h($lbl) ?> · heading</span><input class="sl-in" name="text_h[<?= $pg ?>]" maxlength="60" value="<?= h($txt($pg, 0)) ?>"></label><label class="sl-field"><span class="sl-lab"><?= h($lbl) ?> · button</span><input class="sl-in" name="text_b[<?= $pg ?>]" maxlength="30" value="<?= h($txt($pg, 1)) ?>"></label></div><?php endforeach; ?></section>
<section class="sl-card col g16"><h2 class="sl-ct">Look and motion</h2>
<div class="col g6"><div class="row between"><span class="sl-lab">Blur</span><b class="mono"><output id="ls-blur-o"><?= (int) ($look['blur'] ?? 50) ?></output>%</b></div><input class="ls-rng" type="range" name="blur" min="0" max="100" step="5" value="<?= (int) ($look['blur'] ?? 50) ?>" aria-label="Blur" oninput="document.getElementById('ls-blur-o').value=this.value"><span class="mut sm">50% keeps the picture recognisable and the form easy to read.</span></div>
<div class="col g6"><div class="row between"><span class="sl-lab">Darken</span><b class="mono"><output id="ls-dim-o"><?= (int) ($look['dim'] ?? 30) ?></output>%</b></div><input class="ls-rng" type="range" name="dim" min="0" max="80" step="5" value="<?= (int) ($look['dim'] ?? 30) ?>" aria-label="Darken" oninput="document.getElementById('ls-dim-o').value=this.value"></div>
<label class="sl-field"><span class="sl-lab">Change picture every</span><select class="sl-in" name="interval" style="max-width:220px"><?php foreach ([4, 6, 8, 12] as $s): ?><option value="<?= $s ?>" <?= (int) ($look['interval'] ?? 6) === $s ? 'selected' : '' ?>><?= $s ?> seconds</option><?php endforeach; ?></select></label>
<label class="row g10" style="cursor:pointer"><span class="sl-toggle <?= !empty($look['captions']) ? 'on' : '' ?>" role="switch" aria-checked="<?= !empty($look['captions']) ? 'true' : 'false' ?>" aria-label="Show captions"><input type="hidden" name="captions" value="<?= !empty($look['captions']) ? '1' : '0' ?>"></span><span>Show captions on large screens</span></label>
<div class="row g10 mut sm"><span class="sl-toggle on" role="switch" aria-checked="true" aria-label="Respect reduced motion" data-static></span><span>Sliding always stops for people who turn off motion</span></div></section>
</form>
</div>
<aside class="b col g12" style="position:sticky;top:16px"><div class="row between"><span class="up">Preview</span><span class="mut sm">Picture <?= (int) sl_get($d, 'curN') + 1 ?> · <?= (int) ($look['blur'] ?? 50) ?>% blur (saved values)</span></div>
<div class="sl-seg boxed"><?php foreach ($PG as $p): ?><a class="<?= $pv === $p[0] ? 'on' : '' ?>" href="<?= h(sl_url(['pv' => $p[0]])) ?>" style="display:inline-flex;align-items:center"><?= h($p[1]) ?></a><?php endforeach; ?></div>
<div class="ls-chrome"><span class="ls-fav sm" style="<?= sl_get($d, 'favicon') ? 'background-image:url(' . h(sl_get($d, 'favicon')) . ');background-color:transparent' : '' ?>"><?php if (!sl_get($d, 'favicon')): ?><b>SL</b><?php endif; ?></span><span class="t"><?= sl_v($d, 'site') ?></span><span class="u mono"><?= h(['login' => 'login.php', 'register' => 'sign-up.php', 'forgot' => 'forgot-password.php', 'otp' => 'auth-otp.php'][$pv]) ?></span></div>
<div class="ls-prev"><?php if (in_array($pv, $pages, true) && $cur): ?><div class="bg <?= h($cur['cls']) ?>" style="<?= h($bgSty($cur)) ?>;filter:blur(<?= round(($look['blur'] ?? 50) * 0.16, 1) ?>px)"></div><div class="dim" style="opacity:<?= round(($look['dim'] ?? 30) / 100 + 0.1, 2) ?>"></div><?php endif; ?><div class="card"><span class="row g6"><span class="ls-logo xs" style="<?= sl_get($d, 'logo') ? 'background-image:url(' . h(sl_get($d, 'logo')) . ')' : '' ?>"><?php if (!sl_get($d, 'logo')): ?><span class="sl-logo"><i></i></span><?php endif; ?></span><b class="sm"><?= sl_v($d, 'site') ?></b></span><b class="fw5"><?= h($pv === 'otp' ? $defaults['otp'][0] : $txt($pv, 0)) ?></b><?php foreach ($PF[$pv] as $x): ?><div class="ln"><span><?= h($x) ?></span></div><?php endforeach; ?><div class="btn"><span><?= h($pv === 'otp' ? $defaults['otp'][1] : $txt($pv, 1)) ?></span></div></div><?php if (!empty($look['captions']) && $cur && in_array($pv, $pages, true)): ?><div class="cap"><b><?= h($cur['title']) ?></b><div><?= h($cur['sub']) ?></div></div><?php endif; ?><div class="ls-dots"><?php for ($i = 0; $i < (int) sl_get($d, 'onCount'); $i++): ?><i class="<?= $i === (int) sl_get($d, 'curN') ? 'on' : '' ?>"></i><?php endfor; ?></div></div>
<div class="row g8"><a class="sl-btn ghost sm grow" href="<?= h(sl_url(['n' => max(0, (int) sl_get($d, 'curN') - 1)])) ?>"><i class="ic ic-sm i-left" aria-hidden="true"></i>Previous</a><a class="sl-btn ghost sm grow" href="<?= h(sl_url(['n' => ((int) sl_get($d, 'curN') + 1) % max(1, (int) sl_get($d, 'onCount'))])) ?>">Next<i class="ic ic-sm i-right" aria-hidden="true"></i></a></div>
<div class="sl-card col g6"><span class="fw5 sm">Who can change this</span><span class="mut sm">Staff with the Settings permission (view_tools). Changes are written to Activity Logs.</span></div></aside>
</div>
<script>
(function () { var f = document.getElementById('ls-upload'); if (!f) return; var i = f.querySelector('input[type=file]');
  i.addEventListener('change', function () { if (!i.files.length) return; SL.toast('Uploading…'); SL.post(f.getAttribute('action'), new FormData(f)).then(function (j) { SL.toast(j.message || (j.success ? 'Uploaded' : 'Upload failed'), !j.success); if (j.success) setTimeout(function () { location.reload(); }, 700); }); }); })();
</script>
